CREATE TYPE "conversation_type" AS ENUM (
	'CLASS',
	'PRIVATE'
);

CREATE TABLE IF NOT EXISTS "conversations" (
    "id"            INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "type"          CONVERSATION_TYPE NOT NULL,
    "class_id"      INTEGER UNIQUE,
    "user_a_id"     INTEGER,
    "user_b_id"     INTEGER,
    "created_at"    TIMESTAMP NOT NULL DEFAULT now(),

    PRIMARY KEY("id"),
    UNIQUE("user_a_id", "user_b_id")
);

CREATE TABLE IF NOT EXISTS "messages" (
    "id"                INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "conversation_id"   INTEGER NOT NULL,
    "sender_id"         INTEGER NOT NULL,
    "content"           TEXT NOT NULL,
    "created_at"        TIMESTAMP NOT NULL DEFAULT now(),

    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "conversation_read_states" (
    "id"                    INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "conversation_id"       INTEGER NOT NULL,
    "user_id"               INTEGER NOT NULL,
    "last_read_message_id"  INTEGER,
    "updated_at"            TIMESTAMP NOT NULL DEFAULT now(),

    PRIMARY KEY("id"),
    UNIQUE("conversation_id", "user_id")
);

ALTER TABLE "conversations"
    ADD FOREIGN KEY("class_id") REFERENCES "classes"("id")
        ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "conversations"
    ADD FOREIGN KEY("user_a_id") REFERENCES "users"("id")
        ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "conversations"
    ADD FOREIGN KEY("user_b_id") REFERENCES "users"("id")
        ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "messages"
    ADD FOREIGN KEY("conversation_id") REFERENCES "conversations"("id")
        ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "messages"
    ADD FOREIGN KEY("sender_id") REFERENCES "users"("id")
        ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "conversation_read_states"
    ADD FOREIGN KEY("conversation_id") REFERENCES "conversations"("id")
        ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "conversation_read_states"
    ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
        ON UPDATE NO ACTION ON DELETE RESTRICT;


ALTER TABLE conversations
    ADD CONSTRAINT chk_conversations_type CHECK (
        (type = 'CLASS' AND class_id IS NOT NULL AND user_a_id IS NULL AND user_b_id IS NULL)
            OR (type = 'PRIVATE' AND class_id IS NULL
            AND user_a_id IS NOT NULL AND user_b_id IS NOT NULL AND user_a_id < user_b_id)
        );

ALTER TABLE messages
    ADD CONSTRAINT chk_messages_content CHECK (length(btrim(content)) BETWEEN 1 AND 2000);

CREATE INDEX "idx_messages_conversation_id" ON "messages" ("conversation_id", "id");

CREATE TRIGGER trg_conversation_read_states_updated_at BEFORE UPDATE ON conversation_read_states
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
